test.nexus_product_analytics.temporal_in.raw_code:
select session_id from {{ ref('fct_sessions') }}
where first_query_at<cohort_ts
   or first_completion_at<first_query_at
   or first_completion_at>cohort_ts+{{ var('window_seconds') }}
   or (converted=1 and queried=0)

test.nexus_product_analytics.event_integ.raw_code:
select event_id from {{ ref('stg_events') }}
where event_ts>epoch(cast('{{ var("analysis_cutoff") }}' as timestamptz))
   or latency_ms<0 or cost_usd<0
